<script setup lang="ts">definePageMeta({middleware:'auth'});const route=useRoute(),{api}=useShopApi();const{data:t,refresh}=await useAsyncData(`ticket-${route.params.id}`,()=>api<any>(`/profile/tickets/${route.params.id}`));useHead({title:'گفت‌وگو با پشتیبانی'});const body=ref('');async function reply(){await api(`/profile/tickets/${t.value.id}/replies`,{method:'POST',body:{body:body.value}});body.value='';await refresh()}async function close(){await api(`/profile/tickets/${t.value.id}`,{method:'DELETE'});await navigateTo('/profile/tickets')}</script>
<template><div v-if="t" class="mx-auto max-w-3xl px-4 py-10"><div class="flex justify-between"><div><p class="text-xs text-slate-400">{{t.number}}</p><h1 class="mt-1 text-xl font-black">{{t.subject}}</h1></div><button v-if="t.status!=='closed'" class="text-sm font-bold text-rose-600" @click="close">بستن تیکت</button></div><div class="mt-7 space-y-4"><div v-for="m in t.messages" :key="m.id" :class="['max-w-[85%] rounded-2xl p-5 text-sm leading-8',m.is_staff?'mr-auto bg-brand-700 text-white':'ml-auto border bg-white']"><b class="text-xs">{{m.is_staff?'پشتیبانی':m.user?.name||'شما'}}</b><p class="mt-2">{{m.body}}</p><span class="mt-2 block text-[10px] opacity-60">{{new Date(m.created_at).toLocaleString('fa-IR')}}</span></div></div><form v-if="t.status!=='closed'" class="mt-6 rounded-2xl border bg-white p-4" @submit.prevent="reply"><textarea v-model="body" required rows="3" class="w-full rounded-xl border p-3" placeholder="پاسخ شما…"/><button class="mt-3 rounded-xl bg-brand-700 px-5 py-2.5 font-bold text-white">ارسال پاسخ</button></form></div></template>
